COPY (SELECT coalesce(type,'') AS type, CASE WHEN quality_null_xpac IS NOT FALSE THEN 'unknown' WHEN is_xpac IS TRUE THEN 'xpac' ELSE 'core' END AS corpus_group, count(*)::UBIGINT AS works, count(*) FILTER (WHERE id > 0 AND (is_xpac IS FALSE AND quality_null_xpac IS FALSE) AND is_paratext IS NOT TRUE AND coalesce(type, '') NOT IN ('editorial','erratum','retraction','paratext','peer-review','reference-entry','libguides','supplementary-materials','dataset','database','software','grant','standard','book','dissertation'))::UBIGINT AS selected FROM raw GROUP BY type, corpus_group ORDER BY type, corpus_group) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/inventory.json' (FORMAT JSON, ARRAY true);
CREATE TABLE q AS WITH selected AS (SELECT id,year,trim(field_id) AS field_id, list_sort(list_distinct(list_filter(list_transform(countries,x -> trim(x)),x -> x IS NOT NULL AND x <> ''))) AS countries, list_distinct(list_transform(list_filter(range(1,len(concept_ids0)+1),i -> isfinite(concept_scores0[i]) AND concept_scores0[i] >= 0.0 AND trim(concept_ids0[i]) <> ''),i -> trim(concept_ids0[i]))) AS concepts0_t0, list_distinct(list_transform(list_filter(range(1,len(concept_ids1)+1),i -> isfinite(concept_scores1[i]) AND concept_scores1[i] >= 0.0 AND trim(concept_ids1[i]) <> ''),i -> trim(concept_ids1[i]))) AS concepts1_t0, list_distinct(list_transform(list_filter(range(1,len(concept_ids0)+1),i -> isfinite(concept_scores0[i]) AND concept_scores0[i] >= 0.3 AND trim(concept_ids0[i]) <> ''),i -> trim(concept_ids0[i]))) AS concepts0_t3, list_distinct(list_transform(list_filter(range(1,len(concept_ids1)+1),i -> isfinite(concept_scores1[i]) AND concept_scores1[i] >= 0.3 AND trim(concept_ids1[i]) <> ''),i -> trim(concept_ids1[i]))) AS concepts1_t3, list_distinct(list_transform(list_filter(range(1,len(concept_ids0)+1),i -> isfinite(concept_scores0[i]) AND concept_scores0[i] >= 0.5 AND trim(concept_ids0[i]) <> ''),i -> trim(concept_ids0[i]))) AS concepts0_t5, list_distinct(list_transform(list_filter(range(1,len(concept_ids1)+1),i -> isfinite(concept_scores1[i]) AND concept_scores1[i] >= 0.5 AND trim(concept_ids1[i]) <> ''),i -> trim(concept_ids1[i]))) AS concepts1_t5 FROM raw WHERE id > 0 AND (is_xpac IS FALSE AND quality_null_xpac IS FALSE) AND is_paratext IS NOT TRUE AND coalesce(type, '') NOT IN ('editorial','erratum','retraction','paratext','peer-review','reference-entry','libguides','supplementary-materials','dataset','database','software','grant','standard','book','dissertation')) SELECT id,year,greatest(1,len(countries))::UBIGINT AS country_assignments, CASE WHEN list_contains(countries,'CN') THEN 1.0/len(countries) ELSE 0.0 END AS cn_weight, CASE WHEN list_contains(countries,'US') THEN 1.0/len(countries) ELSE 0.0 END AS us_weight, CASE WHEN list_contains(countries,'GB') THEN 1.0/len(countries) ELSE 0.0 END AS gb_weight, field_id='https://openalex.org/fields/17' AS field17, field_id='https://openalex.org/fields/11' AS field11,CASE WHEN list_contains(concepts0_t3,'https://openalex.org/C86803240') THEN 1.0 ELSE 0.0 END AS biology_weight,greatest(1,len(concepts0_t0))::UBIGINT AS concepts0_t0_assignments,greatest(1,len(concepts1_t0))::UBIGINT AS concepts1_t0_assignments,greatest(1,len(concepts0_t3))::UBIGINT AS concepts0_t3_assignments,greatest(1,len(concepts1_t3))::UBIGINT AS concepts1_t3_assignments,greatest(1,len(concepts0_t5))::UBIGINT AS concepts0_t5_assignments,greatest(1,len(concepts1_t5))::UBIGINT AS concepts1_t5_assignments FROM selected;
COPY (SELECT count(*)::UBIGINT AS selected, count(DISTINCT id)::UBIGINT AS unique_ids FROM q) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/q.json' (FORMAT JSON, ARRAY true);
CREATE TABLE publication_year AS SELECT year, count(*)::UBIGINT AS works, sum(cn_weight * CASE WHEN field17 THEN 1.0 ELSE 0.0 END)::DOUBLE AS cn_f17, sum(cn_weight * CASE WHEN field11 THEN 1.0 ELSE 0.0 END)::DOUBLE AS cn_f11, sum(cn_weight * biology_weight)::DOUBLE AS cn_biology, sum(us_weight * CASE WHEN field17 THEN 1.0 ELSE 0.0 END)::DOUBLE AS us_f17, sum(us_weight * CASE WHEN field11 THEN 1.0 ELSE 0.0 END)::DOUBLE AS us_f11, sum(us_weight * biology_weight)::DOUBLE AS us_biology, sum(gb_weight * CASE WHEN field17 THEN 1.0 ELSE 0.0 END)::DOUBLE AS gb_f17, sum(gb_weight * CASE WHEN field11 THEN 1.0 ELSE 0.0 END)::DOUBLE AS gb_f11, sum(gb_weight * biology_weight)::DOUBLE AS gb_biology,coalesce(sum(country_assignments),0)::UBIGINT AS country_assignments,coalesce(sum(concepts0_t0_assignments),0)::UBIGINT AS concepts0_t0_assignments,coalesce(sum(country_assignments * concepts0_t0_assignments),0)::UBIGINT AS country_concepts0_t0_assignments,coalesce(sum(concepts1_t0_assignments),0)::UBIGINT AS concepts1_t0_assignments,coalesce(sum(country_assignments * concepts1_t0_assignments),0)::UBIGINT AS country_concepts1_t0_assignments,coalesce(sum(concepts0_t3_assignments),0)::UBIGINT AS concepts0_t3_assignments,coalesce(sum(country_assignments * concepts0_t3_assignments),0)::UBIGINT AS country_concepts0_t3_assignments,coalesce(sum(concepts1_t3_assignments),0)::UBIGINT AS concepts1_t3_assignments,coalesce(sum(country_assignments * concepts1_t3_assignments),0)::UBIGINT AS country_concepts1_t3_assignments,coalesce(sum(concepts0_t5_assignments),0)::UBIGINT AS concepts0_t5_assignments,coalesce(sum(country_assignments * concepts0_t5_assignments),0)::UBIGINT AS country_concepts0_t5_assignments,coalesce(sum(concepts1_t5_assignments),0)::UBIGINT AS concepts1_t5_assignments,coalesce(sum(country_assignments * concepts1_t5_assignments),0)::UBIGINT AS country_concepts1_t5_assignments FROM q WHERE year BETWEEN 2000 AND 2026 GROUP BY year;
COPY (SELECT * FROM publication_year ORDER BY year) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/publication_year.json' (FORMAT JSON, ARRAY true);
CREATE TABLE citation_year AS SELECT src.year AS year, count(*) FILTER (WHERE t.id <> src.id)::UBIGINT AS edges, count(*) FILTER (WHERE t.id=src.id)::UBIGINT AS self_loops, count(*) FILTER (WHERE t.year > src.year AND t.id <> src.id)::UBIGINT AS future_edges, coalesce(sum(t.cn_weight * CASE WHEN t.field17 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS cn_f17, coalesce(sum(t.cn_weight * CASE WHEN t.field11 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS cn_f11, coalesce(sum(t.cn_weight * t.biology_weight) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS cn_biology, coalesce(sum(t.us_weight * CASE WHEN t.field17 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS us_f17, coalesce(sum(t.us_weight * CASE WHEN t.field11 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS us_f11, coalesce(sum(t.us_weight * t.biology_weight) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS us_biology, coalesce(sum(t.gb_weight * CASE WHEN t.field17 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS gb_f17, coalesce(sum(t.gb_weight * CASE WHEN t.field11 THEN 1.0 ELSE 0.0 END) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS gb_f11, coalesce(sum(t.gb_weight * t.biology_weight) FILTER (WHERE t.id <> src.id),0)::DOUBLE AS gb_biology,coalesce(sum(t.country_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_assignments,coalesce(sum(t.concepts0_t0_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts0_t0_assignments,coalesce(sum(t.country_assignments * t.concepts0_t0_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts0_t0_assignments,coalesce(sum(t.concepts1_t0_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts1_t0_assignments,coalesce(sum(t.country_assignments * t.concepts1_t0_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts1_t0_assignments,coalesce(sum(t.concepts0_t3_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts0_t3_assignments,coalesce(sum(t.country_assignments * t.concepts0_t3_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts0_t3_assignments,coalesce(sum(t.concepts1_t3_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts1_t3_assignments,coalesce(sum(t.country_assignments * t.concepts1_t3_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts1_t3_assignments,coalesce(sum(t.concepts0_t5_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts0_t5_assignments,coalesce(sum(t.country_assignments * t.concepts0_t5_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts0_t5_assignments,coalesce(sum(t.concepts1_t5_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS concepts1_t5_assignments,coalesce(sum(t.country_assignments * t.concepts1_t5_assignments) FILTER (WHERE t.id <> src.id),0)::UBIGINT AS country_concepts1_t5_assignments FROM (SELECT id,year,"references" AS refs FROM raw WHERE id > 0 AND (is_xpac IS FALSE AND quality_null_xpac IS FALSE) AND is_paratext IS NOT TRUE AND coalesce(type, '') NOT IN ('editorial','erratum','retraction','paratext','peer-review','reference-entry','libguides','supplementary-materials','dataset','database','software','grant','standard','book','dissertation') AND year BETWEEN 2000 AND 2026) src CROSS JOIN UNNEST(list_distinct(src.refs)) AS ref(target_id) JOIN q t ON t.id=ref.target_id WHERE ref.target_id > 0 GROUP BY src.year;
COPY (SELECT * FROM citation_year ORDER BY year) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/citation_year.json' (FORMAT JSON, ARRAY true);
COPY (SELECT 'cube' AS source, 'fractional-concept-whole-0.3' AS scenario_id, scheme,level,year,count(*)::UBIGINT AS rows,sum(publications)::DOUBLE AS publications,sum(citations)::DOUBLE AS citations FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/cube.parquet') GROUP BY scheme,level,year UNION ALL SELECT 'statistics' AS source,scenario_id,scheme,level,year,count(*)::UBIGINT AS rows,sum(publications)::DOUBLE AS publications,sum(citations)::DOUBLE AS citations FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/statistics.parquet') GROUP BY scenario_id,scheme,level,year) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/output_year.json' (FORMAT JSON, ARRAY true);
COPY (SELECT 'cube' AS source,country,scheme,level,discipline_id,year,sum(publications)::DOUBLE AS publications,sum(citations)::DOUBLE AS citations FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/cube.parquet') WHERE country IN ('CN','US','GB') AND ((scheme='topics' AND level='field' AND discipline_id IN ('https://openalex.org/fields/17','https://openalex.org/fields/11')) OR (scheme='concepts' AND level='0' AND discipline_id='https://openalex.org/C86803240')) GROUP BY country,scheme,level,discipline_id,year UNION ALL SELECT 'statistics' AS source,country,scheme,level,discipline_id,year,sum(publications)::DOUBLE AS publications,sum(citations)::DOUBLE AS citations FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/statistics.parquet') WHERE scenario_id='fractional-concept-whole-0.3' AND country IN ('CN','US','GB') AND ((scheme='topics' AND level='field' AND discipline_id IN ('https://openalex.org/fields/17','https://openalex.org/fields/11')) OR (scheme='concepts' AND level='0' AND discipline_id='https://openalex.org/C86803240')) GROUP BY country,scheme,level,discipline_id,year) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/output_cells.json' (FORMAT JSON, ARRAY true);
COPY (SELECT (SELECT count(*) FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/cube.parquet'))::UBIGINT AS cube_rows, (SELECT count(*) FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/statistics.parquet'))::UBIGINT AS statistics_rows) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/output_counts.json' (FORMAT JSON, ARRAY true);
CREATE TABLE audit_labels AS SELECT layer.scheme AS scheme,layer.level AS level,label.id AS discipline_id FROM read_json_auto('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/dictionary.json') doc, UNNEST(doc.layers) ls(layer), UNNEST(layer.labels) ds(label);
CREATE TABLE audit_countries AS SELECT country_label.id AS country FROM read_json_auto('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/dictionary.json') doc, UNNEST(doc.countries) cs(country_label);
COPY (SELECT count(*) FILTER (WHERE country_mode='whole' AND concept_mode='whole' AND (publications IS NULL OR citations IS NULL OR NOT isfinite(publications) OR NOT isfinite(citations) OR publications<0 OR citations<0 OR publications<>trunc(publications) OR citations<>trunc(citations)))::UBIGINT AS invalid_whole_integers, count(*) FILTER (WHERE publications IS NULL OR citations IS NULL OR NOT isfinite(publications) OR NOT isfinite(citations) OR publications<0 OR citations<0)::UBIGINT AS invalid_counts, count(*) FILTER (WHERE scheme IS NULL OR level IS NULL OR year IS NULL OR NOT ((scheme='topics' AND level IN ('field','subfield')) OR (scheme='concepts' AND level IN ('0','1'))) OR year NOT BETWEEN 2000 AND 2026 OR country IS NULL OR trim(country)='' OR discipline_id IS NULL OR trim(discipline_id)='')::UBIGINT AS invalid_dimensions, count(*) FILTER (WHERE ((scenario_id='fractional-concept-whole-0.0' AND country_mode='fractional' AND concept_mode='whole' AND concept_threshold=0 AND main=false) OR (scenario_id='fractional-concept-whole-0.3' AND country_mode='fractional' AND concept_mode='whole' AND concept_threshold=0.3 AND main=true) OR (scenario_id='fractional-concept-whole-0.5' AND country_mode='fractional' AND concept_mode='whole' AND concept_threshold=0.5 AND main=false) OR (scenario_id='whole-concept-whole-0.0' AND country_mode='whole' AND concept_mode='whole' AND concept_threshold=0 AND main=false) OR (scenario_id='whole-concept-whole-0.3' AND country_mode='whole' AND concept_mode='whole' AND concept_threshold=0.3 AND main=true) OR (scenario_id='whole-concept-whole-0.5' AND country_mode='whole' AND concept_mode='whole' AND concept_threshold=0.5 AND main=false)) IS NOT TRUE)::UBIGINT AS invalid_scenario_metadata, count(*) FILTER (WHERE (discipline_id<>'UNKNOWN' AND d.discipline_id IS NULL) OR (country<>'UNKNOWN' AND c.country IS NULL))::UBIGINT AS invalid_dictionary_labels FROM read_parquet('/mnt/nvme0/public/openalex-stats/results/core-concept-hits-v1/statistics.parquet') s LEFT JOIN audit_labels d USING(scheme,level,discipline_id) LEFT JOIN audit_countries c USING(country)) TO '/mnt/nvme1/backup/openalex-stats/core-concept-hits-audit-v1/output_integrity.json' (FORMAT JSON, ARRAY true);
